3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import {
8	  registrarConfigured,
9	  registrarSafeMessage,
10	  listRecords,
11	  addRecord,
12	  deleteRecord,
13	  type DnsRecord,
14	  lockDomain,
15	  unlockDomain,
16	  isDomainLocked,
17	  listUrlForwarding,
18	  addUrlForwarding,
19	  deleteUrlForwarding,
20	} from "./registrar";
21	
22	/* ------------------------------------------------------------------ *
23	 * DNS super-manager actions for the customer domain manager.
24	 *
25	 * Reuses lib/registrar.ts's DNS helpers (listRecords/addRecord/
26	 * deleteRecord) for all record mutations, plus its URL-forwarding and
27	 * registrar-lock helpers. Everything is ownership-checked and degrades
28	 * gracefully (persist intent + a clear note) when the registrar isn't
29	 * configured or a TLD/endpoint isn't supported.
30	 * ------------------------------------------------------------------ */
31	
32	function errMsg(e: unknown): string {
33	  return registrarSafeMessage(e);
34	}
35	
36	async function ownedDomain(domainId: string) {
37	  const user = await requireUser();
38	  const domain = await db.domain.findUnique({ where: { id: domainId } });
39	  if (!domain) throw new Error("Not found");
40	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
41	  return { user, domain };
42	}
43	
44	async function ownedActiveDomain(domainId: string) {
45	  const ctx = await ownedDomain(domainId);
46	  if (ctx.domain.status !== "ACTIVE") throw new Error("Domain is not active");
47	  if (!registrarConfigured()) throw new Error("Domain registration is not configured yet");
48	  return ctx;
49	}
50	
51	/* A record shape the client can build for presets / imports. Host "" = apex. */
52	export type RecordInput = {
53	  host: string;
54	  type: string;
55	  answer: string;
56	  ttl?: number;
57	  priority?: number;
58	};
59	
60	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
61	
62	function normHost(h: string): string {
63	  const t = (h ?? "").trim();
64	  return ["@", ""].includes(t) ? "" : t.replace(/\.$/, "");
65	}
66	
67	/** True if `want` is already present in `existing` (host+type+answer, MX also priority). */
68	function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
69	  const wh = normHost(want.host);
70	  const wa = want.answer.trim().toLowerCase();
71	  return existing.some((r) => {
72	    if (r.host !== wh) return false;
73	    if (r.type !== want.type) return false;
74	    if (r.answer.trim().toLowerCase() !== wa) return false;
75	    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
76	    return true;
77	  });
78	}
79	
80	const recordInputSchema = z.object({
81	  host: z.string().max(120).default(""),
82	  type: z.enum(RECORD_TYPES),
83	  answer: z.string().min(1).max(2000),
84	  ttl: z.coerce.number().int().min(60).max(86400).default(300),
85	  priority: z.coerce.number().int().min(0).max(65535).optional(),
86	});
87	
88	export type BulkResult = {
89	  error?: string;
90	  added?: string[];
91	  skipped?: string[];
92	  failed?: { record: string; reason: string }[];
93	  note?: string;
94	};
95	
96	function label(r: RecordInput): string {
97	  const h = normHost(r.host) || "@";
98	  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
99	  return `${r.type} ${h} → ${pri}${r.answer}`;
100	}
101	
102	/**
103	 * Add many DNS records at once, skipping any that already exist. Powers the
104	 * quick-setup presets and DNS import. Ownership-checked; domain must be ACTIVE.
105	 */
106	export async function addDnsRecordsBulk(
107	  domainId: string,
108	  records: RecordInput[]
109	): Promise<BulkResult> {
110	  let ctx;
111	  try {
112	    ctx = await ownedActiveDomain(domainId);
113	  } catch (e) {
114	    return { error: errMsg(e) };
115	  }
116	  if (!Array.isArray(records) || records.length === 0) return { error: "No records to add." };
117	  if (records.length > 100) return { error: "Too many records in one request (max 100)." };
118	
119	  const clean: RecordInput[] = [];
120	  for (const raw of records) {
121	    const parsed = recordInputSchema.safeParse(raw);
122	    if (!parsed.success) {
123	      return { error: `Invalid record: ${parsed.error.issues[0]?.message ?? "bad record"}` };
124	    }
125	    clean.push({ ...parsed.data, host: normHost(parsed.data.host) });
126	  }
127	
128	  let existing: DnsRecord[];
129	  try {
130	    existing = await listRecords(ctx.domain.name);
131	  } catch (e) {
132	    return { error: `Could not read current records: ${errMsg(e)}` };
133	  }
134	
135	  const added: string[] = [];
136	  const skipped: string[] = [];
137	  const failed: { record: string; reason: string }[] = [];
138	
139	  for (const rec of clean) {
140	    if (recordExists(existing, rec)) {
141	      skipped.push(label(rec));
142	      continue;
143	    }
144	    try {
145	      await addRecord(ctx.domain.name, {
146	        host: rec.host,
147	        type: rec.type,
148	        answer: rec.answer,
149	        ttl: rec.ttl ?? 300,
150	        priority: rec.type === "MX" || rec.type === "SRV" ? rec.priority ?? 10 : undefined,
151	      });
152	      added.push(label(rec));
153	      // Track locally so later records in the same batch dedupe correctly.
154	      existing.push({ id: -1, host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 300, priority: rec.priority });
155	    } catch (e) {
156	      failed.push({ record: label(rec), reason: errMsg(e) });
157	    }
158	  }
159	
160	  await db.auditLog.create({
161	    data: {
162	      userId: ctx.user.id,
163	      action: "domain.dns_bulk_add",
164	      detail: `${ctx.domain.name}: +${added.length} skip ${skipped.length} fail ${failed.length}`,
165	    },
166	  });
167	  revalidatePath(`/dashboard/domains/${domainId}`);
168	  return { added, skipped, failed: failed.length ? failed : undefined };
169	}
170	
171	/* ------------------------------------------------------------------ *
172	 * DNS import (paste) — CSV / zone-ish text: name,type,value[,ttl[,priority]]
173	 * Lines starting with # or ; are ignored. Whitespace or comma separated.
174	 * ------------------------------------------------------------------ */
175	
176	export type ParsedImport = { records: RecordInput[]; errors: string[] };
177	
178	/** Pure parser exported so the UI can preview before applying. */
179	export async function parseDnsImport(text: string): Promise<ParsedImport> {
180	  const records: RecordInput[] = [];
181	  const errors: string[] = [];
182	  const lines = (text ?? "").split(/\r?\n/);
183	  lines.forEach((line, i) => {
184	    const raw = line.trim();
185	    if (!raw || raw.startsWith("#") || raw.startsWith(";")) return;
186	    // split on comma OR whitespace, but keep the value token intact if quoted
187	    let parts: string[];
188	    if (raw.includes(",")) parts = raw.split(",").map((p) => p.trim());
189	    else parts = raw.split(/\s+/);
190	    if (parts.length < 3) {
191	      errors.push(`Line ${i + 1}: expected at least name, type, value`);
192	      return;
193	    }
194	    const [nameTok, typeTok, valueTok, ttlTok, prioTok] = parts;
195	    const type = typeTok.toUpperCase();
196	    if (!(RECORD_TYPES as readonly string[]).includes(type)) {
197	      errors.push(`Line ${i + 1}: unsupported type "${typeTok}"`);
198	      return;
199	    }
200	    const value = valueTok.replace(/^"|"$/g, "");
201	    const rec: RecordInput = { host: normHost(nameTok), type, answer: value };
202	    if (ttlTok && /^\d+$/.test(ttlTok)) rec.ttl = Math.min(86400, Math.max(60, Number(ttlTok)));
203	    if (type === "MX" && prioTok && /^\d+$/.test(prioTok)) rec.priority = Number(prioTok);
204	    records.push(rec);
205	  });
206	  return { records, errors };
207	}
208	
209	export async function importDnsRecords(domainId: string, text: string): Promise<BulkResult> {
210	  const { records, errors } = await parseDnsImport(text);
211	  if (errors.length && records.length === 0) {
212	    return { error: errors.join("; ").slice(0, 300) };
213	  }
214	  const res = await addDnsRecordsBulk(domainId, records);
215	  if (errors.length) {
216	    res.note = `${errors.length} line(s) skipped: ${errors.slice(0, 3).join("; ")}${errors.length > 3 ? "…" : ""}`;
217	  }
218	  return res;
219	}
220	
221	/* ------------------------------------------------------------------ *
222	 * Reset DNS to a sane default set (strong confirm handled in the UI).
223	 * Removes all customer-manageable records (A/AAAA/CNAME/TXT/MX/SRV/ALIAS),
224	 * leaves NS delegation untouched, then re-adds A @ / A www at the platform IP.
225	 * ------------------------------------------------------------------ */
226	
227	export async function resetDnsToDefaults(domainId: string): Promise<BulkResult> {
228	  let ctx;
229	  try {
230	    ctx = await ownedActiveDomain(domainId);
231	  } catch (e) {
232	    return { error: errMsg(e) };
233	  }
234	  const ip = process.env.PUBLIC_IP;
235	  const removable = new Set(["A", "AAAA", "CNAME", "TXT", "MX", "SRV", "ALIAS"]);
236	  let removed = 0;
237	  const failed: { record: string; reason: string }[] = [];
238	  try {
239	    const recs = await listRecords(ctx.domain.name);
240	    for (const r of recs) {
241	      if (!removable.has(r.type)) continue;
242	      try {
243	        await deleteRecord(ctx.domain.name, r.id);
244	        removed++;
245	      } catch (e) {
246	        failed.push({ record: `${r.type} ${r.host || "@"}`, reason: errMsg(e) });
247	      }
248	    }
249	  } catch (e) {
250	    return { error: `Could not read current records: ${errMsg(e)}` };
251	  }
252	
253	  const added: string[] = [];
254	  if (ip) {
255	    for (const host of ["", "www"]) {
256	      try {
257	        await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
258	        added.push(`A ${host || "@"} → ${ip}`);
259	      } catch (e) {
260	        failed.push({ record: `A ${host || "@"}`, reason: errMsg(e) });
261	      }
262	    }
263	  }
264	
265	  await db.auditLog.create({
266	    data: { userId: ctx.user.id, action: "domain.dns_reset", detail: `${ctx.domain.name}: removed ${removed}, added ${added.length}` },
267	  });
268	  revalidatePath(`/dashboard/domains/${domainId}`);
269	  return {
270	    added,
271	    skipped: [],
272	    failed: failed.length ? failed : undefined,
273	    note: `Removed ${removed} record(s)${added.length ? ` and restored a default A record set pointing at ${ip}` : " (no platform IP configured, so no default records were added)"}.`,
274	  };
275	}
276	
277	/* ------------------------------------------------------------------ *
278	 * URL forwarding / redirects (name.com URL-forwarding API).
279	 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
280	 * Degrades to a persisted-intent Setting + note when unconfigured.
281	 * ------------------------------------------------------------------ */
282	
283	export type Redirect = { host: string; forwardsTo: string; type: string };
284	
285	const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;
286	
287	async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
288	  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
289	  if (!s?.value) return [];
290	  try {
291	    const parsed = JSON.parse(s.value);
292	    return Array.isArray(parsed) ? parsed : [];
293	  } catch {
294	    return [];
295	  }
296	}
297	
298	async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
299	  await db.setting.upsert({
300	    where: { key: redirectStoreKey(domainId) },
301	    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
302	    update: { value: JSON.stringify(list) },
303	  });
304	}
305	
306	export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };
307	
308	/** List forwardings — live from name.com when possible, else persisted intent. */
309	export async function listRedirects(domainId: string): Promise<RedirectsView> {
310	  let ctx;
311	  try {
312	    ctx = await ownedDomain(domainId);
313	  } catch (e) {
314	    return { forwards: [], live: false, error: errMsg(e) };
315	  }
316	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
317	    try {
318	      const forwards = await listUrlForwarding(ctx.domain.name);
319	      return { forwards, live: true };
320	    } catch (e) {
321	      // Fall back to intent store but tell the truth about why.
322	      const forwards = await readRedirectIntent(domainId);
323	      return { forwards, live: false, note: `Live forwarding unavailable (${errMsg(e)}); showing saved intent.` };
324	    }
325	  }
326	  const forwards = await readRedirectIntent(domainId);
327	  return { forwards, live: false, note: "Registrar not connected — showing saved intent that will apply once live." };
328	}
329	
330	const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;
331	
332	export async function setRedirect(
333	  domainId: string,
334	  hostRaw: string,
335	  forwardsTo: string,
336	  type: string
337	): Promise<RedirectsView> {
338	  let ctx;
339	  try {
340	    ctx = await ownedDomain(domainId);
341	  } catch (e) {
342	    return { forwards: [], live: false, error: errMsg(e) };
343	  }
344	  const host = normHost(hostRaw);
345	  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
346	  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
347	  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };
348	
349	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
350	  if (canLive) {
351	    try {
352	      // Upsert: delete any existing forwarding for this host, then create.
353	      try {
354	        await deleteUrlForwarding(ctx.domain.name, host);
355	      } catch {
356	        /* none existed */
357	      }
358	      await addUrlForwarding(ctx.domain.name, { host, forwardsTo: url.data, type: t });
359	    } catch (e) {
360	      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
361	    }
362	  } else {
363	    const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
364	    list.push({ host, forwardsTo: url.data, type: t });
365	    await writeRedirectIntent(domainId, list);
366	  }
367	
368	  await db.auditLog.create({
