414	export async function getRegistrarLock(domainId: string): Promise<LockView> {
415	  let ctx;
416	  try {
417	    ctx = await ownedDomain(domainId);
418	  } catch (e) {
419	    return { locked: false, live: false, error: errMsg(e) };
420	  }
421	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
422	    try {
423	      const locked = await isDomainLocked(ctx.domain.name);
424	      return { locked, live: true };
425	    } catch {
426	      /* fall through to stored intent */
427	    }
428	  }
429	  const s = await db.setting.findUnique({ where: { key: lockStoreKey(domainId) } });
430	  return { locked: s?.value === "true", live: false };
