89	/**
90	 * Persist the WHOIS-privacy preference. name.com's privacy is a paid add-on
91	 * set at registration rather than a free live toggle, so this is persisted-
92	 * only: we record intent and surface a note. Ownership-checked.
93	 */
94	export async function setWhoisPrivacy(
95	  domainId: string,
96	  enabled: boolean
97	): Promise<{ error?: string; whoisPrivacy?: boolean; note?: string }> {
98	  const { user } = await ownedDomain(domainId);
99	
100	  await db.domain.update({ where: { id: domainId }, data: { whoisPrivacy: enabled } });
101	  await db.auditLog.create({
