1	/**
2	 * Batched, cached, globally-throttled, MULTI-REGISTRAR availability lookups
3	 * for the public domain-name generator and the signed-in domain wizard.
4	 *
5	 * Each configured registrar (`lib/registrars/index.ts`'s `configuredRegistrars()`
6	 * — env-configured AND admin-enabled) is a METERED third-party API, so three
7	 * protections sit in front of EACH one independently:
8	 *
9	 *   1. CACHE     — a short-TTL in-process map keyed by `(registrarId, domain)`,
10	 *                  since two registrars quoting the same domain are two
11	 *                  different facts, not one.
12	 *   2. BATCHING  — each registrar's `checkDomains` takes an array, so a whole
13	 *                  page of candidates is as few upstream calls as that
14	 *                  registrar's own real per-call limit allows (see
15	 *                  `BATCH_SIZE_BY_REGISTRAR` below — verified per registrar,
16	 *                  never assumed to match another).
17	 *   3. GLOBAL CAP — a process-wide sliding window PER REGISTRAR
18	 *                  (`registrar:availability:<id>:global`), so one registrar's
19	 *                  outage/slowness/rate-limit can never throttle the others.
20	 *
21	 * MERGE (see `mergeCheapest` below for the full rule): the cheapest
22	 * `available: true` result across registrars wins, EVEN over a disagreeing
23	 * "taken" from another registrar (registries can be out of sync with each
24	 * other); a domain is "taken" only when no registrar says available; "unknown"
25	 * only when EVERY registrar came back unknown (down, throttled, or simply not
26	 * configured at all). Registrar identity
27	 * never appears on the merged result — `DomainResult` carries no registrar
28	 * id, by construction, so it cannot leak into the client bundle (see
29	 * `test/registrar-leak-guard.test.ts`).
30	 *
31	 * Prices are only ever what a registrar actually returned. When neither
32	 * registrar gives us a price we surface no price — never an estimate, never a
33	 * TLD average.
34	 */
35	
36	import { checkRateLimit } from "@/lib/rate-limit";
37	import { configuredRegistrars, type DomainCheck, type RegistrarClient } from "@/lib/registrars";
38	
39	/**
40	 * Max domains sent in a single upstream `checkDomains` call, PER REGISTRAR.
41	 *
42	 * name.com: verified working at 24 (see git history — this repo's own prior
43	 * single-registrar constant). Namecheap: its API docs do not publish a
44	 * documented maximum for `domains.check`'s comma-separated `DomainList` (only
45	 * an overall 50 calls/min · 700/hour · 8000/day per-key rate limit is
46	 * documented) — 20 is a deliberately conservative choice pending real-world
47	 * verification once Namecheap can actually authenticate (see
48	 * lib/registrars/namecheap.ts's file header for why it can't yet). Do NOT
49	 * assume this number is confirmed the way name.com's is.
50	 */
51	const BATCH_SIZE_BY_REGISTRAR: Record<string, number> = {
52	  namecom: 24,
53	  namecheap: 20,
54	};
55	const DEFAULT_BATCH_SIZE = 20;
56	
57	/** Cache lifetime. Long enough to absorb re-rolls, short enough to stay honest. */
58	const CACHE_TTL_MS = 10 * 60 * 1000;
59	
60	/** Hard ceiling on entries so the map can't grow unbounded. */
61	const CACHE_MAX = 4000;
62	
63	/** Process-wide registrar budget: batches per minute across ALL visitors, PER REGISTRAR. */
64	const GLOBAL_BATCHES_PER_MIN = 60;
65	
66	type Entry = { at: number; check: DomainCheck };
67	
68	/** Cache key: `(registrarId, domain)` — two registrars quoting the same domain are two different facts. */
69	const cacheKey = (registrarId: string, domain: string) => `${registrarId}:${domain}`;
70	
71	const localCache = new Map<string, Entry>();
72	// Survive HMR / route reloads in dev so the cache actually caches.
73	const globalForCache = globalThis as unknown as { __nxeonDomainAvail?: Map<string, Entry> };
74	const cache: Map<string, Entry> = globalForCache.__nxeonDomainAvail ?? localCache;
75	if (process.env.NODE_ENV !== "production") globalForCache.__nxeonDomainAvail = cache;
76	
77	function readCache(registrarId: string, domain: string, now: number): DomainCheck | null {
78	  const key = cacheKey(registrarId, domain);
79	  const hit = cache.get(key);
80	  if (!hit) return null;
81	  if (now - hit.at > CACHE_TTL_MS) {
82	    cache.delete(key);
83	    return null;
84	  }
85	  return hit.check;
86	}
87	
88	function writeCache(registrarId: string, check: DomainCheck, now: number): void {
89	  if (cache.size >= CACHE_MAX) {
90	    // Drop the oldest ~10% rather than clearing everything on a cold spike.
91	    const victims = [...cache.entries()]
92	      .sort((a, b) => a[1].at - b[1].at)
93	      .slice(0, Math.ceil(CACHE_MAX / 10));
94	    for (const [k] of victims) cache.delete(k);
95	  }
96	  cache.set(cacheKey(registrarId, check.domain), { at: now, check });
97	}
98	
99	export type AvailabilityStatus = "available" | "taken" | "unknown";
100	
101	export type DomainResult = {
102	  domain: string;
103	  status: AvailabilityStatus;
104	  premium: boolean;
105	  /** Retail first-year price in integer cents, or null when no registrar gave one. */
106	  priceCents: number | null;
107	  /** Retail renewal price in integer cents, or null. */
108	  renewCents: number | null;
109	};
110	
111	export type AvailabilityOutcome = {
112	  results: DomainResult[];
113	  /** False when NO registrar is configured+enabled at all — everything is "unknown". */
114	  configured: boolean;
115	  /** True when at least one registrar's lookup was skipped to protect its shared upstream budget. */
116	  throttled: boolean;
117	  /** How many (registrar, domain) lookups were served from cache rather than a registrar. */
118	  cached: number;
119	};
120	
121	function toResult(check: DomainCheck): DomainResult {
122	  // A registrar only prices a purchasable name; a taken domain comes back priceless.
123	  const available = check.available && check.priceCents !== null;
124	  return {
125	    domain: check.domain,
126	    status: available ? "available" : "taken",
127	    premium: check.premium,
128	    priceCents: available ? check.priceCents : null,
129	    renewCents: available ? check.renewCents : null,
130	  };
131	}
132	
133	function unknown(domain: string): DomainResult {
134	  return { domain, status: "unknown", premium: false, priceCents: null, renewCents: null };
135	}
136	
137	/**
138	 * Merge one domain's per-registrar results into the single result the
139	 * customer sees. Pure and exported for testing — this is the one place
140	 * "which registrar's price wins" is decided.
141	 *
142	 *   - At least one "available" (with a price) -> "available", cheapest price
143	 *     wins. This takes priority over a DISAGREEING "taken" from another
144	 *     registrar — registries can be out of sync with each other by minutes to
145	 *     hours, and the multi-registrar plan's own recommendation for this exact
146	 *     case (see its Open Questions) is "available if any configured registrar
147	 *     says available with a price; taken only if none do" — a false "taken"
148	 *     costs nothing, a false "available" that then fails to register is worse.
149	 *   - Else at least one "taken" -> "taken".
150	 *   - Else -> "unknown" (every registrar was down/throttled/unconfigured) —
151	 *     never fabricated as available or taken.
152	 *
153	 * A genuine available/taken disagreement between registrars is logged (not
154	 * silently resolved) so ops can see how often it actually happens.
155	 *
156	 * `results` must be non-empty; each entry ideally already carries `domain`
157	 * matching the domain being merged (not checked here — the caller guarantees it).
158	 */
159	export function mergeCheapest(domain: string, results: DomainResult[]): DomainResult {
160	  const available = results.filter((r) => r.status === "available" && r.priceCents !== null);
161	  const anyTaken = results.some((r) => r.status === "taken");
162	  if (available.length > 0) {
163	    if (anyTaken) {
164	      console.error(`[registrar] availability disagreement for ${domain}: at least one registrar says available, another says taken — showing available`);
165	    }
166	    return available.reduce((best, r) => (r.priceCents! < best.priceCents! ? r : best));
167	  }
168	  if (anyTaken) {
169	    // Prefer a "taken" entry's own shape (e.g. its `premium` flag) over a synthesized one.
170	    return results.find((r) => r.status === "taken") ?? { domain, status: "taken", premium: false, priceCents: null, renewCents: null };
171	  }
172	  return unknown(domain);
173	}
174	
175	/** One registrar's resolved results for a batch of domains, plus its own throttle/cache stats. */
176	async function resolveForRegistrar(
177	  registrar: RegistrarClient,
178	  domains: string[],
179	  now: number
180	): Promise<{ results: Map<string, DomainResult>; throttled: boolean; cached: number }> {
181	  const resolved = new Map<string, DomainResult>();
182	  const misses: string[] = [];
183	  for (const d of domains) {
184	    const hit = readCache(registrar.id, d, now);
185	    if (hit) resolved.set(d, toResult(hit));
186	    else misses.push(d);
187	  }
188	  const cached = resolved.size;
189	
190	  let throttled = false;
191	  const batchSize = BATCH_SIZE_BY_REGISTRAR[registrar.id] ?? DEFAULT_BATCH_SIZE;
192	  const batches: string[][] = [];
193	  for (let i = 0; i < misses.length; i += batchSize) batches.push(misses.slice(i, i + batchSize));
194	
195	  for (const batch of batches) {
196	    // Shared upstream budget — checked per batch, not per domain, PER REGISTRAR
197	    // so one registrar's outage/rate-limit can't throttle the others.
198	    const budget = checkRateLimit(`registrar:availability:${registrar.id}:global`, {
199	      max: GLOBAL_BATCHES_PER_MIN,
200	      windowMs: 60_000,
201	    });
202	    if (!budget.ok) {
203	      throttled = true;
204	      for (const d of batch) resolved.set(d, unknown(d));
205	      continue;
206	    }
207	
208	    try {
209	      const checks = await registrar.checkDomains(batch);
210	      const seen = new Set<string>();
211	      for (const check of checks) {
212	        const key = check.domain.toLowerCase();
213	        seen.add(key);
214	        writeCache(registrar.id, { ...check, domain: key }, now);
215	        resolved.set(key, toResult(check));
216	      }
217	      // A domain this registrar simply didn't answer for stays honest.
218	      for (const d of batch) if (!seen.has(d)) resolved.set(d, unknown(d));
219	    } catch {
220	      for (const d of batch) resolved.set(d, unknown(d));
221	    }
222	  }
223	
224	  return { results: resolved, throttled, cached };
225	}
226	
227	/**
228	 * Look up availability for a list of domains, preserving input order, fanned
229	 * out across every configured+enabled registrar and merged to the cheapest
230	 * available price (see `mergeCheapest`).
231	 *
232	 * Never throws: a registrar outage degrades every uncached domain to `unknown`
233	 * so the page still renders names, clearly marked as unverified.
234	 */
235	export async function checkAvailabilityBatched(domains: string[]): Promise<AvailabilityOutcome> {
236	  const now = Date.now();
237	  const unique = [...new Set(domains.map((d) => d.toLowerCase()))];
238	
239	  const registrars = await configuredRegistrars();
240	  if (registrars.length === 0) {
241	    return { results: unique.map(unknown), configured: false, throttled: false, cached: 0 };
242	  }
243	
244	  // Per-registrar deadline for the CUSTOMER-FACING search response specifically.
245	  // Found live: Namecheap's users.getPricing (its TLD price list — see
246	  // lib/registrars/namecheap.ts's tldPricingMap) takes ~18s on a cold cache
247	  // (process-scoped, wiped on every restart), while name.com answers in well
248	  // under a second. Without this, one slow-but-not-actually-down registrar
249	  // blocks the whole search for every visitor until its cache warms up — the
250	  // opposite of this file's own stated goal ("one registrar's outage/slowness
251	  // can never throttle the others"), which until now only covered hard
252	  // failures and rate-limiting, not plain slowness. A registrar that misses
253	  // this deadline contributes nothing for THIS call (never a fabricated
254	  // price) — its own cache still gets populated by the in-flight call
255	  // finishing in the background, so the NEXT search is fast.
256	  const SEARCH_DEADLINE_MS = 6_000;
257	  const withDeadline = (p: Promise<{ results: Map<string, DomainResult>; throttled: boolean; cached: number }>) =>
258	    Promise.race([
259	      p,
260	      new Promise<{ results: Map<string, DomainResult>; throttled: boolean; cached: number }>((resolve) =>
261	        setTimeout(() => resolve({ results: new Map(), throttled: false, cached: 0 }), SEARCH_DEADLINE_MS)
262	      ),
263	    ]);
264	  const perRegistrar = await Promise.all(registrars.map((r) => withDeadline(resolveForRegistrar(r, unique, now))));
265	
266	  let throttled = false;
267	  let cached = 0;
268	  for (const outcome of perRegistrar) {
269	    throttled = throttled || outcome.throttled;
270	    cached += outcome.cached;
271	  }
272	
273	  const results = unique.map((d) => {
274	    const candidates = perRegistrar.map((o) => o.results.get(d) ?? unknown(d));
275	    return mergeCheapest(d, candidates);
276	  });
277	
278	  return { results, configured: true, throttled, cached };
279	}
280	
281	/** `$12.99` from integer cents. Returns null so callers can't print a fake price. */
282	export function formatPrice(cents: number | null): string | null {
283	  if (cents === null || !Number.isFinite(cents)) return null;
284	  return `$${(cents / 100).toFixed(2)}`;
285	}
