45	const typeTone: Record<string, "brand" | "green" | "amber" | "slate"> = {
46	  A: "green",
47	  AAAA: "green",
48	  CNAME: "brand",
49	  MX: "amber",
50	  TXT: "slate",
51	  NS: "brand",
52	  SRV: "slate",
53	};
