15	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
16	
17	export default async function RegisterDomainPage({
18	  searchParams,
19	}: {
20	  searchParams: Promise<{ domain?: string }>;
21	}) {
22	  const user = await requireUser();
23	  const { domain: raw } = await searchParams;
24	  const domain = (raw ?? "").toLowerCase().trim();
25	  const valid = DOMAIN_RE.test(domain);
26	  const configured = registrarConfigured();
27	
28	  if (!configured) {
29	    return (
30	      <div className="space-y-6">
31	        <PortalHero variant="domains" title="Register domain" />
32	        <EmptyState
33	          title="Domain registration is not available yet"
34	          sub="Registration activates once this feature is configured. Your existing domains stay manageable in the meantime."
35	          action={
36	            <Link href="/dashboard/domains" className="btn-primary">
37	              Back to domains
38	            </Link>
39	          }
40	        />
41	      </div>
42	    );
43	  }
44	
45	  // Live availability + price for the pre-selected domain (best-effort). Mapped
46	  // into the shared DomainCheckResult shape (status + sld/tld) the wizard uses.
47	  let initialCheck: DomainCheckResult | null = null;
48	  if (valid) {
49	    try {
50	      const [check] = await checkDomains([domain]);
51	      if (check) {
52	        const dot = check.domain.indexOf(".");
53	        const available = check.available && check.priceCents !== null;
54	        initialCheck = {
55	          domain: check.domain,
56	          sld: dot > 0 ? check.domain.slice(0, dot) : check.domain,
57	          tld: dot > 0 ? check.domain.slice(dot + 1) : "",
58	          status: available ? "available" : "taken",
59	          available,
60	          premium: check.premium,
61	          priceCents: available ? check.priceCents : null,
62	          renewCents: available ? check.renewCents : null,
63	        };
64	      }
65	    } catch {
66	      /* registrar briefly unreachable — the wizard can re-check client-side */
67	    }
68	  }
69	
70	  // Real, live figures for the free-mailbox-with-hosting card below — sourced
71	  // from the same HostingPlan rows the /web-hosting pricing table reads, never
72	  // a guessed number. Shared Web Hosting bundles free mailboxes on every plan
73	  // (HostingPlan.mailboxes); Business Email bought on its own is never free
74	  // (see lib/actions-email-hosting.ts — firstMonthFreeAppliesTo("EMAIL") is
75	  // false), so the offer here is specifically "free mailbox WITH hosting."
76	  const hostingPlans = await db.hostingPlan.findMany({
77	    where: { active: true },
78	    select: { priceCents: true, mailboxes: true },
79	    orderBy: { priceCents: "asc" },
80	  });
81	  const hostingFromCents = hostingPlans.length ? hostingPlans[0].priceCents : null;
82	  const maxBundledMailboxes = hostingPlans.length
83	    ? Math.max(...hostingPlans.map((p) => p.mailboxes))
84	    : null;
85	
86	  // The real, free "Domain Inbox" plan every Nxeon registration now includes
87	  // (lib/domain-inbox-email.ts). Null until prisma/seed-domain-inbox-plan.ts
88	  // has been run on this environment — the wizard's Email step is skipped
89	  // entirely rather than claiming a feature that isn't actually seeded yet.
90	  const inboxPlan = await findDomainInboxPlan();
91	
92	  return (
93	    <div className="space-y-6">
94	      <PortalHero variant="domains" title="Register domain" sub="A few quick steps to secure your name.">
95	        <Link href="/dashboard/domains/ideas" className="btn-secondary">
96	          Need a name?
97	        </Link>
98	        <Link href="/dashboard/domains" className="btn-ghost">
99	          ← All domains
100	        </Link>
101	      </PortalHero>
102	
103	      {hostingFromCents !== null && (
104	        <div className="card flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
105	          <div className="flex items-start gap-4">
106	            <span className="flex h-11 w-11 flex-none items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-300">
107	              <IconMail size={22} />
108	            </span>
109	            <div>
110	              <h2 className="font-semibold text-white">Get a free mailbox with hosting</h2>
111	              <p className="mt-1 max-w-xl text-sm text-slate-400">
112	                Nxeon Web Hosting bundles{" "}
113	                {maxBundledMailboxes && maxBundledMailboxes > 1 ? `up to ${maxBundledMailboxes}` : "a"}{" "}
114	                professional you@yourdomain mailbox{maxBundledMailboxes === 1 ? "" : "es"} free with every
115	                plan — no separate email bill. Plans start at {fmtMoney(hostingFromCents)}/mo, and your
116	                first month is free.
117	              </p>
118	            </div>
119	          </div>
120	          <Link href="/web-hosting" className="btn-secondary shrink-0 self-start sm:self-center">
121	            See hosting plans
122	          </Link>
123	        </div>
124	      )}
