126	      <DomainRegisterWizard
127	        initialDomain={valid ? domain : ""}
128	        initialCheck={initialCheck}
129	        defaultEmail={user.email}
130	        balanceCents={user.balanceCents}
131	        freeInboxPlan={inboxPlan ? { mailboxes: inboxPlan.mailboxes, storageGB: inboxPlan.storageGB } : null}
132	        geoapifyEnabled={geoapifyConfigured()}
133	      />
134	    </div>
135	  );
