109	/**
110	 * The domains the signed-in user has PROVEN they control.
111	 *
112	 * `verified: true` is load-bearing, not decoration. An alias is a mail-routing
113	 * change (`mcAddAlias` makes the shared Mailcow deliver an address somewhere),
114	 * so treating a bare subscription row as proof of domain control let a claimed —
115	 * not owned — domain silently intercept inbound mail. Same root cause as the
116	 * 2026-07-25 cross-tenant takeover: owning the ROW is not owning the DOMAIN.
117	 */
118	async function ownedDomains(userId: string): Promise<Set<string>> {
119	  const subs = await db.emailSubscription.findMany({
120	    where: { userId, status: { not: "CANCELLED" }, verified: true },
121	    select: { domainName: true },
122	  });
123	  return new Set(subs.map((s) => s.domainName.trim().toLowerCase()).filter(Boolean));
124	}
125	
126	// ---------------------------------------------------------------------------
127	// Identity, signature, auto-reply (stored on the Mailbox row)
128	// ---------------------------------------------------------------------------
129	
130	/** Load the current settings for a mailbox the caller owns. */
131	// ---------------------------------------------------------------------------
132	// Mailbox-row helpers — a resolved mailboxId is either a customer Mailbox.id or,
133	// for a staff-resolved COMPANY mailbox, "company:<CompanyMailbox.id>". Both
134	// tables now carry the same settings columns, so identity/signature/auto-reply/
135	// forwarding read and write the same way regardless of which backs the mailbox.
136	// This is the fix for the P2025 crash on Save changes: db.mailbox.update() threw
137	// for company mailboxes because no Mailbox row exists for them.
138	// ---------------------------------------------------------------------------
139	
140	function companyRowId(mailboxId: string): string | null {
141	  return mailboxId.startsWith("company:") ? mailboxId.slice("company:".length) : null;
142	}
143	
144	/** Read the settings-bearing row for a resolved mailbox from whichever table backs it. */
145	async function loadMailboxRow(mailboxId: string) {
146	  const cid = companyRowId(mailboxId);
147	  return cid
148	    ? db.companyMailbox.findUnique({ where: { id: cid } })
149	    : db.mailbox.findUnique({ where: { id: mailboxId } });
150	}
151	
152	/** Persist settings to whichever table backs the resolved mailbox (customer Mailbox or CompanyMailbox). */
153	async function updateMailboxRow(mailboxId: string, data: Prisma.MailboxUncheckedUpdateInput): Promise<void> {
154	  const cid = companyRowId(mailboxId);
155	  if (cid) {
156	    await db.companyMailbox.update({ where: { id: cid }, data: data as Prisma.CompanyMailboxUncheckedUpdateInput });
157	  } else {
158	    await db.mailbox.update({ where: { id: mailboxId }, data });
159	  }
160	}
161	
162	export async function getMailboxSettings(mailboxAddress?: string): Promise<MailboxSettings> {
163	  const { mailboxId, address } = await resolveMailbox(mailboxAddress);
164	  const row = await loadMailboxRow(mailboxId);
165	  const placement = row?.signaturePlacement === "above" ? "above" : "below";
166	  return {
167	    address,
168	    domain: domainOf(address),
169	    displayName: row?.displayName ?? "",
170	    replyTo: row?.replyTo ?? "",
171	    organization: row?.organization ?? "",
172	    signature: row?.signature ?? "",
173	    signatureHtml: row?.signatureHtml ?? "",
174	    signatureEnabled: row?.signatureEnabled ?? true,
175	    signatureOnReply: row?.signatureOnReply ?? true,
176	    signaturePlacement: placement,
177	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
178	    autoReplySubject: row?.autoReplySubject ?? "",
179	    autoReplyBody: row?.autoReplyBody ?? "",
180	    autoReplyStart: toDateInput(row?.autoReplyStart),
181	    autoReplyEnd: toDateInput(row?.autoReplyEnd),
182	    forwardingAddress: row?.forwardingAddress ?? "",
183	    forwardKeepCopy: row?.forwardKeepCopy ?? true,
184	    quotaMB: row?.quotaMB ?? null,
185	  };
