137	// ---------- Mutations ----------
138	
139	/** Create a mail domain (idempotent-ish: if it already exists Mailcow errors,
140	 * which callers may ignore). */
141	export async function mcCreateDomain(domain: string): Promise<unknown> {
142	  return mcRequest("POST", "/add/domain", {
143	    domain,
144	    description: `nxeon ${domain}`,
145	    aliases: 400,
146	    mailboxes: 100,
147	    defquota: 1024,
148	    maxquota: 102400,
149	    // Domain TOTAL quota. This must never be the binding constraint: mailboxes are
150	    // provisioned at up to `maxquota` (100 GB) and a plan sells up to 25 of them, so
151	    // a flat 100 GB here (the old value) silently capped every domain at TWO 50 GB
152	    // mailboxes and failed the 3rd with `mailbox_quota_left_exceeded`. Set it to
153	    // mailboxes × maxquota so the real limits — per-mailbox size and the plan's
154	    // mailbox count, both enforced in the app — are what actually govern capacity.
