228	// ---------- Mailbox discovery (read-only) ----------
229	
230	/** A mailbox as it actually exists on Mailcow, narrowed to what we can adopt. */
231	export type MailcowMailbox = {
232	  address: string; // Mailcow's `username` — the full email address
233	  domain: string;
234	  name: string;
235	  active: boolean;
236	  quotaBytes: number;
237	  quotaUsedBytes: number;
238	};
