240	/**
241	 * List the mailboxes that really exist on a domain (`GET /get/mailbox/all/<domain>`).
242	 *
243	 * WHY this exists: `resolveMailbox` used to read only `db.mailbox`, so a mailbox
244	 * that lives on Mailcow without a local row was completely invisible in the
245	 * portal — the "it's not detecting the mailbox I already have on this account"
246	 * report. This is the read half of the reconciliation; the adoption half
247	 * (lib/mail/imap.ts `discoverMailboxes`) gates on domain verification.
248	 *
249	 * A domain Mailcow doesn't know returns `{}`, which we normalise to `[]`.
250	 */
251	export async function mcListMailboxes(domain: string): Promise<MailcowMailbox[]> {
252	  const res = await mcRequest("GET", `/get/mailbox/all/${encodeURIComponent(domain)}`);
253	  const rows = Array.isArray(res) ? res : [];
254	  const want = domain.trim().toLowerCase();
255	  const out: MailcowMailbox[] = [];
256	  for (const r of rows) {
257	    if (!r || typeof r !== "object") continue;
258	    const o = r as Record<string, unknown>;
259	    const address = typeof o.username === "string" ? o.username.trim().toLowerCase() : "";
260	    if (!address.includes("@")) continue;
261	    const mboxDomain =
262	      typeof o.domain === "string" ? o.domain.trim().toLowerCase() : address.slice(address.lastIndexOf("@") + 1);
263	    // Never return a row for a different domain than the one asked for — the
264	    // caller uses the domain to decide ownership, so it must not be spoofable
265	    // by a surprising API response shape.
266	    if (mboxDomain !== want) continue;
267	    out.push({
268	      address,
269	      domain: mboxDomain,
270	      name: typeof o.name === "string" ? o.name : "",
271	      active: toActive(o.active),
272	      quotaBytes: Number(o.quota) > 0 ? Number(o.quota) : 0,
273	      quotaUsedBytes: Number(o.quota_used) > 0 ? Number(o.quota_used) : 0,
274	    });
275	  }
276	  return out;
277	}
