340	
341	/**
342	 * A per-mailbox sieve filter as stored in Mailcow's `sieve_filters` table.
343	 *
344	 * Mailcow chains scripts as: global_sieve_before -> user `prefilter` ->
345	 * the user's own personal script -> user `postfilter` -> global_sieve_after.
346	 * Only ONE filter per (username, filter_type) can be active at a time —
347	 * Mailcow deactivates the others whenever a filter is added/edited as active.
348	 * That is why lib/mail/sieve.ts compiles auto-reply AND forwarding into a
349	 * single managed script instead of one filter each.
350	 */
351	export type MailcowFilter = {
352	  id: number;
353	  username: string;
354	  scriptDesc: string;
355	  scriptData: string;
356	  filterType: string; // "prefilter" | "postfilter"
357	  active: boolean;
358	};
359	
360	export type MailcowFilterType = "prefilter" | "postfilter";
361	
362	function toFilterRows(res: unknown): MailcowFilter[] {
363	  const rows = Array.isArray(res) ? res : [];
364	  const out: MailcowFilter[] = [];
365	  for (const r of rows) {
366	    if (!r || typeof r !== "object") continue;
367	    const o = r as Record<string, unknown>;
368	    const id = Number(o.id);
369	    if (!Number.isFinite(id)) continue;
370	    out.push({
371	      id,
372	      username: typeof o.username === "string" ? o.username : "",
373	      scriptDesc: typeof o.script_desc === "string" ? o.script_desc : "",
374	      scriptData: typeof o.script_data === "string" ? o.script_data : "",
375	      filterType: typeof o.filter_type === "string" ? o.filter_type : "",
376	      active: toActive(o.active),
377	    });
378	  }
379	  return out;
380	}
