382	/**
383	 * List the sieve filters belonging to ONE mailbox
384	 * (`GET /get/filters/<address>`). Mailcow returns `{}` when there are none.
385	 *
386	 * Always pass a full address: `/get/filters/all` walks every domain on the
387	 * server, which would leak other tenants' scripts into our result.
388	 */
389	export async function mcListFilters(address: string): Promise<MailcowFilter[]> {
390	  const res = await mcRequest("GET", `/get/filters/${encodeURIComponent(address)}`);
391	  // Defence in depth: Mailcow scopes by username server-side, but we re-filter
392	  // so a wrong/greedy response can never hand one customer another's script.
393	  const want = address.trim().toLowerCase();
394	  return toFilterRows(res).filter((f) => f.username.trim().toLowerCase() === want);
395	}
