444	// ---------- DKIM ----------
445	
446	/**
447	 * Fetch the DKIM public-key TXT value for a domain from Mailcow
448	 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
449	 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
450	 * or null when the domain has no DKIM key yet or the shape is unexpected.
451	 *
452	 * Throws MailcowError only when the integration is unreachable/errors — callers
453	 * that must stay tolerant wrap this in try/catch.
454	 */
455	export async function mcGetDkim(domain: string): Promise<string | null> {
456	  return (await mcGetDkimDetails(domain))?.txt ?? null;
457	}
458	
459	/** The signing key Mailcow will actually use, plus the selector it publishes under. */
460	export type MailcowDkim = { selector: string; txt: string; bits: number | null };
461	
462	/**
463	 * Fetch the LIVE DKIM key + selector for a domain.
464	 *
465	 * The deliverability self-check must compare published DNS against this, never
466	 * against `EmailSubscription.dkimRecord`: that column is a cache written once at
467	 * DNS-setup time, so if the key is ever rotated (or the domain re-created on
468	 * Mailcow, which regenerates it) the cache silently describes a key that no
469	 * longer signs anything — and the check would tell a customer their DNS is
470	 * correct while every message they send fails DKIM.
471	 */
472	export async function mcGetDkimDetails(domain: string): Promise<MailcowDkim | null> {
473	  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
474	  if (!res || typeof res !== "object") return null;
475	  // Mailcow returns {} for a domain with no key configured.
476	  const o = res as Record<string, unknown>;
477	  const txt = typeof o.dkim_txt === "string" ? o.dkim_txt.trim() : "";
478	  if (!txt) return null;
479	  const selector = typeof o.dkim_selector === "string" && o.dkim_selector.trim() ? o.dkim_selector.trim() : "dkim";
480	  const bits = Number(o.length);
481	  return { selector, txt, bits: Number.isFinite(bits) && bits > 0 ? bits : null };
482	}
