484	// ---------- Analytics ----------
485	
486	export type MailStats = {
487	  configured: true;
488	  domains: number;
489	  mailboxes: number;
490	  postfix: {
491	    sampled: number;
492	    sent: number;
493	    deferred: number;
494	    bounced: number;
495	    rejected: number;
496	    other: number;
497	  };
498	  rspamd: {
499	    sampled: number;
500	    actions: Record<string, number>;
501	    spam: number; // reject + add header + rewrite subject
502	    clean: number; // no action + greylist / soft reject
503	  };
504	};
505	
506	function asArray(v: unknown): unknown[] {
507	  if (Array.isArray(v)) return v;
508	  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
509	    return (v as { rows: unknown[] }).rows;
510	  }
511	  return [];
512	}
