514	/**
515	 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
516	 * deliverability view. Throws (MailcowError) if not configured or unreachable —
517	 * the admin page catches that and shows a graceful fallback.
518	 */
519	export async function mcStats(sample = 400): Promise<MailStats> {
520	  config(); // throws early with a clear message if not configured
521	
522	  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
523	    mcRequest("GET", "/get/domain/all").catch(() => []),
524	    mcRequest("GET", "/get/mailbox/all").catch(() => []),
525	    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
526	    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
527	  ]);
528	
529	  const postfixLogs = asArray(postfixRaw);
530	  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
531	  for (const entry of postfixLogs) {
532	    const msg = String(
533	      (entry as { message?: unknown })?.message ??
534	        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
535	        "",
536	    ).toLowerCase();
537	    if (msg.includes("status=sent")) postfix.sent++;
538	    else if (msg.includes("status=deferred")) postfix.deferred++;
539	    else if (msg.includes("status=bounced")) postfix.bounced++;
540	    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
541	    else postfix.other++;
542	  }
543	
544	  const rspamdLogs = asArray(rspamdRaw);
545	  const actions: Record<string, number> = {};
546	  let spam = 0;
547	  let clean = 0;
548	  for (const entry of rspamdLogs) {
549	    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
550	    actions[action] = (actions[action] ?? 0) + 1;
551	    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
552	    else clean++;
553	  }
554	
555	  return {
556	    configured: true,
557	    domains: asArray(domainsRaw).length,
558	    mailboxes: asArray(mailboxesRaw).length,
559	    postfix,
560	    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
561	  };
562	}
