68	export type SendAttachment = {
69	  filename: string;
70	  contentType: string; // MIME type; server defaults to application/octet-stream
71	  contentBase64: string; // raw base64 (no "data:*;base64," prefix)
72	  /**
73	   * When set, this attachment is an INLINE image referenced from the HTML body
74	   * as `src="cid:<cid>"`. The send path gives it this Content-ID and marks it
75	   * `inline` so mail clients render it in-place (multipart/related) instead of
76	   * listing it as a download. Absent = an ordinary attached file.
