1	// Per-domain mail deliverability self-check (SPF / DKIM / DMARC / MX).
2	//
3	// Plain server-side module (NO "use server") — the ownership-checked server
4	// action lives in lib/actions-email-hosting.ts.
5	//
6	// WHY: customers land in spam with no way to find out why. That is exactly what
7	// happened to the platform owner: mail was silently failing authentication and
8	// the only diagnosis available was an external third-party tool. This gives every
9	// customer a pass/fail per record with the value we ACTUALLY observed next to the
10	// value we expect, so "my mail goes to spam" becomes a fixable DNS row.
11	//
12	// ============================ THE RESOLVER TRAP =============================
13	// This check MUST NOT use the system resolver. This host has:
14	//
15	//     /etc/nsswitch.conf -> hosts: files myhostname dns
16	//
17	// and a populated /etc/hosts. During today's incident a reverse lookup returned a
18	// value straight out of that local text file while appearing to have asked
19	// Cloudflare and Google — which produced a completely confident, completely wrong
20	// diagnosis. A customer-facing check built on the system resolver would tell
21	// people their DNS is broken when it is fine, or the reverse.
22	//
23	// So: resolve the zone's NS records through PINNED public resolvers, resolve
24	// those nameservers to IPs, then query THOSE nameservers directly for every
25	// record. The answer then comes from the zone's own authority — no /etc/hosts, no
26	// inherited /etc/resolv.conf, no recursive-cache staleness after the customer
27	// has just fixed a record.
28	// ============================================================================
29	
30	import { Resolver } from "node:dns/promises";
31	
32	/** Public resolvers used ONLY to find the zone's nameservers. Never the OS list. */
33	const BOOTSTRAP_RESOLVERS = ["1.1.1.1", "8.8.8.8", "9.9.9.9"];
34	
35	const DNS_TIMEOUT_MS = 4000;
36	const DNS_TRIES = 2;
37	
38	export type CheckStatus = "pass" | "warn" | "fail" | "unknown";
39	
40	export type DeliverabilityCheck = {
41	  key: "mx" | "spf" | "dkim" | "dmarc";
42	  label: string;
43	  status: CheckStatus;
44	  /** What the authoritative nameservers actually returned (empty = nothing published). */
45	  observed: string;
46	  /** What we need to see there. */
47	  expected: string;
48	  /** One line the customer can act on. */
49	  detail: string;
50	  /** The DNS name that was queried, so the customer knows which row to edit. */
51	  host: string;
52	  type: "MX" | "TXT";
53	};
54	
55	export type DeliverabilityReport = {
56	  domain: string;
57	  /** The authoritative nameservers we queried — shown so the result is auditable. */
58	  nameservers: string[];
59	  checks: DeliverabilityCheck[];
60	  /** Set when we could not establish authority at all (checks will be `unknown`). */
61	  error?: string;
62	  checkedAt: string;
63	};
64	
65	function bootstrapResolver(): Resolver {
66	  const r = new Resolver({ timeout: DNS_TIMEOUT_MS, tries: DNS_TRIES });
67	  // Explicit setServers is the entire point — a bare `new Resolver()` inherits
68	  // /etc/resolv.conf, which is the failure mode described at the top of this file.
69	  r.setServers(BOOTSTRAP_RESOLVERS);
70	  return r;
71	}
72	
73	/** All parent zones of a name, apex last: a.b.example.com -> b.example.com, example.com. */
74	function parentZones(domain: string): string[] {
75	  const labels = domain.split(".").filter(Boolean);
76	  const out: string[] = [];
77	  for (let i = 0; i < labels.length - 1; i++) out.push(labels.slice(i).join("."));
78	  return out;
79	}
80	
81	/**
82	 * Find the zone's authoritative nameservers and return a Resolver pinned to them.
83	 *
84	 * Walks up from the queried name because a mail domain can be a subdomain whose
85	 * NS records live on the parent zone; without the walk a perfectly healthy
86	 * `mail.customer.com` would report "we can't find your nameservers".
87	 */
88	export async function authoritativeResolver(
89	  domain: string,
90	): Promise<{ resolver: Resolver; nameservers: string[] } | { error: string }> {
91	  const boot = bootstrapResolver();
92	
93	  let nameservers: string[] = [];
94	  for (const zone of [domain, ...parentZones(domain)]) {
95	    try {
96	      const ns = await boot.resolveNs(zone);
97	      if (ns.length > 0) {
98	        nameservers = ns.map((n) => n.replace(/\.$/, "").toLowerCase());
99	        break;
100	      }
101	    } catch {
102	      // NXDOMAIN / ENODATA at this level — try the parent zone.
103	    }
104	  }
105	  if (nameservers.length === 0) {
106	    return { error: "No nameservers found for this domain — check it is registered and delegated." };
107	  }
108	
109	  const ips: string[] = [];
110	  for (const ns of nameservers) {
111	    const [v4, v6] = await Promise.all([
112	      boot.resolve4(ns).catch(() => [] as string[]),
113	      boot.resolve6(ns).catch(() => [] as string[]),
114	    ]);
115	    ips.push(...v4, ...v6);
116	  }
117	  if (ips.length === 0) {
118	    return { error: `Could not resolve this domain's nameservers (${nameservers.join(", ")}) to an address.` };
119	  }
120	
121	  const resolver = new Resolver({ timeout: DNS_TIMEOUT_MS, tries: DNS_TRIES });
122	  resolver.setServers(ips);
123	  return { resolver, nameservers };
124	}
125	
126	/** A TXT record's chunks are concatenated with NO separator (RFC 7208 §3.3). */
127	function joinTxt(record: string[]): string {
128	  return record.join("").trim();
129	}
130	
131	export async function txtAt(resolver: Resolver, host: string): Promise<string[] | null> {
132	  try {
133	    return (await resolver.resolveTxt(host)).map(joinTxt).filter(Boolean);
134	  } catch {
135	    // NXDOMAIN / ENODATA from the authority means "not published".
136	    return null;
137	  }
138	}
139	
140	/**
141	 * CNAME target(s) at `host`, resolved through the authoritative nameservers, or
142	 * null when nothing is published. Used for the cold-email tracking-domain check.
143	 */
144	export async function cnameAt(resolver: Resolver, host: string): Promise<string[] | null> {
145	  try {
146	    const targets = (await resolver.resolveCname(host)).map((c) => c.replace(/\.$/, "").toLowerCase()).filter(Boolean);
147	    return targets.length ? targets : null;
148	  } catch {
149	    return null;
150	  }
151	}
152	
153	/** Normalise a DKIM TXT value so cosmetic differences don't read as a mismatch. */
154	function dkimKey(value: string): string {
155	  const m = value.match(/(?:^|[;\s])p=([A-Za-z0-9+/=]*)/);
156	  return m ? m[1] : "";
157	}
158	
159	function truncate(v: string, max = 180): string {
160	  return v.length > max ? `${v.slice(0, max)}…` : v;
161	}
162	
163	/**
164	 * Run the four authentication checks for `domain`.
165	 *
166	 * `mailHost` is the MX we expect, `spfInclude` the mechanism that authorises our
167	 * sending host, and `dkim` MUST be the LIVE key read from Mailcow
168	 * (`GET /get/dkim/<domain>` → `dkim_txt`), never the cached
169	 * `EmailSubscription.dkimRecord`: a stale cache would confirm a key that no
170	 * longer signs anything.
171	 */
172	export async function checkDeliverability(opts: {
173	  domain: string;
174	  mailHost: string;
175	  spfInclude: string;
176	  spfExpected: string;
177	  dmarcExpected: string;
178	  dkim: { selector: string; txt: string } | null;
179	}): Promise<DeliverabilityReport> {
180	  const domain = opts.domain.trim().toLowerCase().replace(/\.$/, "");
181	  const checkedAt = new Date().toISOString();
182	  const dkimSelector = opts.dkim?.selector || "dkim";
183	  const dkimHost = `${dkimSelector}._domainkey.${domain}`;
184	
185	  const auth = await authoritativeResolver(domain);
186	  if ("error" in auth) {
187	    const unknown = (
188	      key: DeliverabilityCheck["key"],
189	      label: string,
190	      host: string,
191	      type: DeliverabilityCheck["type"],
192	      expected: string,
193	    ): DeliverabilityCheck => ({
194	      key,
195	      label,
196	      status: "unknown",
197	      observed: "",
198	      expected,
199	      detail: "Couldn't reach this domain's nameservers to read the record.",
200	      host,
201	      type,
202	    });
203	    return {
204	      domain,
205	      nameservers: [],
206	      error: auth.error,
207	      checkedAt,
208	      checks: [
209	        unknown("mx", "MX — mail routing", domain, "MX", opts.mailHost),
210	        unknown("spf", "SPF — authorised senders", domain, "TXT", opts.spfExpected),
211	        unknown("dkim", "DKIM — message signing", dkimHost, "TXT", opts.dkim?.txt ?? "(no key on the mail server yet)"),
212	        unknown("dmarc", "DMARC — policy", `_dmarc.${domain}`, "TXT", opts.dmarcExpected),
213	      ],
214	    };
215	  }
216	
217	  const { resolver, nameservers } = auth;
218	
219	  const [mxRecords, apexTxt, dkimTxt, dmarcTxt] = await Promise.all([
220	    resolver.resolveMx(domain).catch(() => null),
221	    txtAt(resolver, domain),
222	    txtAt(resolver, dkimHost),
223	    txtAt(resolver, `_dmarc.${domain}`),
224	  ]);
225	
226	  const checks: DeliverabilityCheck[] = [];
227	
228	  // ---- MX ----------------------------------------------------------------
229	  {
230	    const rows = (mxRecords ?? []).map((r) => ({
231	      exchange: r.exchange.replace(/\.$/, "").toLowerCase(),
232	      priority: r.priority,
233	    }));
234	    const observed = rows.length
235	      ? rows
236	          .slice()
237	          .sort((a, b) => a.priority - b.priority)
238	          .map((r) => `${r.exchange} (${r.priority})`)
239	          .join(", ")
240	      : "";
241	    const ours = rows.some((r) => r.exchange === opts.mailHost);
242	    checks.push({
243	      key: "mx",
244	      label: "MX — mail routing",
245	      status: ours ? (rows.length > 1 ? "warn" : "pass") : "fail",
246	      observed,
247	      // Hostname only, deliberately: the setup panel suggests priority 10, but any
248	      // priority works when this is the only MX. Printing "(priority 10)" next to
249	      // a healthy `mail.nxeon.cloud (1)` made a passing row look like a mismatch.
250	      expected: opts.mailHost,
251	      host: domain,
252	      type: "MX",
253	      detail: !rows.length
254	        ? `No MX record published — inbound mail for this domain has nowhere to go. Add an MX for ${opts.mailHost} at priority 10.`
255	        : ours
256	          ? rows.length > 1
257	            ? "Our mail host is listed, but so are others — mail may be delivered to a different server."
258	            : "Inbound mail is routed to the Nxeon mail server."
259	          : `Mail is routed elsewhere. Point the MX at ${opts.mailHost} (priority 10) or inbound mail will never reach these mailboxes.`,
260	    });
261	  }
262	
263	  // ---- SPF ---------------------------------------------------------------
264	  {
265	    const spfRecords = (apexTxt ?? []).filter((t) => /^v=spf1\b/i.test(t));
266	    const observed = spfRecords.join(" | ");
267	    let status: CheckStatus = "fail";
268	    let detail: string;
269	    if (spfRecords.length === 0) {
270	      detail = "No SPF record published — receivers have nothing authorising us to send for you.";
271	    } else if (spfRecords.length > 1) {
272	      status = "fail";
273	      detail = "More than one SPF record. RFC 7208 makes that a permanent error — merge them into one.";
274	    } else {
275	      const spf = spfRecords[0];
276	      const authorised =
277	        spf.toLowerCase().includes(`include:${opts.spfInclude}`) ||
278	        // `mx` authorises whatever the MX points at, which is our mail host when
279	        // the MX check above passes — a valid, commonly-used alternative.
280	        /(?:^|\s)mx(?:\s|$)/i.test(spf);
281	      if (authorised) {
282	        status = /[~-]all\s*$/.test(spf) ? "pass" : "warn";
283	        detail =
284	          status === "pass"
285	            ? "The Nxeon mail server is authorised to send for this domain."
286	            : "Authorised, but the record has no `~all`/`-all` terminator, so receivers apply no policy to unauthorised senders.";
287	      } else {
288	        detail = `SPF exists but doesn't authorise us. Add \`include:${opts.spfInclude}\` (or \`mx\`) or your mail will be treated as spoofed.`;
289	      }
290	    }
291	    checks.push({
292	      key: "spf",
293	      label: "SPF — authorised senders",
294	      status,
295	      observed,
296	      expected: opts.spfExpected,
297	      host: domain,
298	      type: "TXT",
299	      detail,
300	    });
301	  }
302	
303	  // ---- DKIM --------------------------------------------------------------
304	  {
305	    const published = (dkimTxt ?? []).find((t) => /(?:^|[;\s])p=/.test(t)) ?? "";
306	    const expected = opts.dkim?.txt ?? "";
307	    let status: CheckStatus = "fail";
308	    let detail: string;
309	    if (!expected) {
310	      status = "unknown";
311	      detail =
312	        "The mail server hasn't generated a DKIM key for this domain yet — there is nothing to publish. Reload in a moment.";
313	    } else if (!published) {
314	      detail = `No DKIM record at ${dkimHost}. Without it every message you send is unsigned, which is the single biggest reason mail lands in spam.`;
315	    } else if (dkimKey(published) && dkimKey(published) === dkimKey(expected)) {
316	      status = "pass";
317	      detail = `Published key matches the one the mail server signs with (selector \`${dkimSelector}\`).`;
318	    } else {
319	      detail =
320	        "A DKIM record exists but the public key does not match the mail server's current key — signatures will fail. Replace it with the value shown here.";
321	    }
322	    checks.push({
323	      key: "dkim",
324	      label: "DKIM — message signing",
325	      status,
326	      observed: truncate(published),
327	      expected: truncate(expected || "(no key on the mail server yet)"),
328	      host: dkimHost,
329	      type: "TXT",
330	      detail,
331	    });
332	  }
333	
334	  // ---- DMARC -------------------------------------------------------------
335	  {
336	    const records = (dmarcTxt ?? []).filter((t) => /^v=DMARC1\b/i.test(t));
337	    const observed = records.join(" | ");
338	    let status: CheckStatus = "fail";
339	    let detail: string;
340	    if (records.length === 0) {
341	      detail =
342	        "No DMARC record. Some large providers now require one before they will trust bulk mail from a domain.";
343	    } else if (records.length > 1) {
344	      detail = "More than one DMARC record at _dmarc — receivers ignore all of them. Keep exactly one.";
345	    } else {
346	      const policy = records[0].match(/(?:^|;)\s*p\s*=\s*(none|quarantine|reject)/i)?.[1]?.toLowerCase();
347	      status = policy ? "pass" : "warn";
348	      detail = policy
349	        ? `Policy \`p=${policy}\` is published${policy === "none" ? " (monitor-only — tighten it once SPF and DKIM both pass)" : ""}.`
350	        : "A DMARC record exists but declares no `p=` policy, so receivers have nothing to enforce.";
351	    }
352	    checks.push({
353	      key: "dmarc",
354	      label: "DMARC — policy",
355	      status,
356	      observed,
357	      expected: opts.dmarcExpected,
358	      host: `_dmarc.${domain}`,
359	      type: "TXT",
360	      detail,
361	    });
362	  }
363	
364	  return { domain, nameservers, checks, checkedAt };
365	}
