76	/** The signed-in user's mailboxes with used/quota bytes (best effort per box). */
77	export async function getMailboxes(): Promise<MailboxInfo[]> {
78	  const user = await requireUser();
79	  const boxes = await db.mailbox.findMany({
80	    where: { subscription: { userId: user.id } },
81	    include: { subscription: true },
82	    orderBy: { createdAt: "asc" },
83	  });
84	
85	  const out: MailboxInfo[] = [];
86	  for (const box of boxes) {
87	    const quotaBytes = box.quotaMB ? box.quotaMB * 1024 * 1024 : 0;
88	    const password = decryptSecret(box.passwordEnc);
89	    let usedBytes = 0;
90	    let liveQuota = quotaBytes;
91	    if (password) {
92	      try {
93	        const q = await withImap({ address: box.address, password }, async (client) => {
94	          const quota = await client.getQuota().catch(() => false as const);
95	          if (quota && quota.storage) return quota.storage;
96	          // Fall back to STATUS SIZE on INBOX where QUOTA isn't advertised.
97	          const st = await client.status("INBOX", { size: true }).catch(() => null);
98	          return st?.size != null ? { used: st.size, limit: quotaBytes } : null;
99	        });
100	        if (q) {
101	          usedBytes = q.used ?? 0;
102	          if (q.limit && q.limit > 0) liveQuota = q.limit;
103	        }
104	      } catch {
105	        /* connection/auth issue — report zero usage rather than failing the page */
106	      }
107	    }
108	    out.push({ address: box.address, usedBytes, quotaBytes: liveQuota });
109	  }
110	  // NOTE: company mailboxes (admin@, support@, …) are intentionally NOT listed
111	  // here — they live entirely in the admin portal's Inbox (see
112	  // lib/actions-company-mail.ts → listCompanyMailboxInfos), never in a customer's
113	  // /dashboard/mail switcher.
114	  return out;
115	}
