121	/** List the mailbox's folders with unread/total counts and their role. */
122	export async function listFolders(mailboxAddress?: string): Promise<MailFolder[]> {
123	  const { cred } = await resolveMailbox(mailboxAddress);
124	  return withImap(cred, async (client) => {
125	    const list = await client.list({ statusQuery: { messages: true, unseen: true } });
126	    const folders: MailFolder[] = [];
127	    for (const f of list) {
128	      // Skip containers that can't hold messages.
129	      if (f.flags?.has("\\Noselect")) continue;
130	      folders.push({
131	        path: f.path,
132	        name: f.name || f.path,
133	        role: folderRole(f.path, f.specialUse),
134	        unread: f.status?.unseen ?? 0,
135	        total: f.status?.messages ?? 0,
136	      });
137	    }
138	    // Stable, useful ordering: known roles first, then custom alphabetically.
139	    const order: Record<string, number> = { inbox: 0, sent: 1, drafts: 2, archive: 3, junk: 4, trash: 5, custom: 6 };
140	    folders.sort((a, b) => (order[a.role] - order[b.role]) || a.name.localeCompare(b.name));
141	    return folders;
142	  });
143	}
