149	/** Decode a downloaded body part (transfer-encoding already decoded by server). */
150	function decodeCharset(buf: Buffer, charset?: string): string {
151	  const cs = (charset || "").toLowerCase();
152	  if (/latin1|8859|1252/.test(cs)) return buf.toString("latin1");
153	  return buf.toString("utf8");
154	}
