156	/** Fetch a short, transfer-decoded snippet of a message's text part for preview. */
157	async function fetchPreview(client: ImapFlow, uid: number, part: string): Promise<string> {
158	  try {
159	    const { meta, content } = await client.download(String(uid), part, { uid: true, maxBytes: 4096 });
160	    const chunks: Buffer[] = [];
161	    for await (const chunk of content) chunks.push(chunk as Buffer);
162	    return previewText(decodeCharset(Buffer.concat(chunks), meta.charset));
163	  } catch {
164	    return "";
165	  }
166	}
