168	/**
169	 * List a page of messages (newest first). `search` runs an IMAP SEARCH across
170	 * subject / from / to / body. Envelopes + a light body snippet only — never the
171	 * full body — so lists stay cheap.
172	 */
173	export async function listMessages(
174	  folder: string,
175	  page: number,
176	  search?: string,
177	  mailboxAddress?: string,
178	): Promise<ListResult> {
179	  const { cred } = await resolveMailbox(mailboxAddress);
180	  const pageNum = Math.max(1, Math.floor(page) || 1);
181	
182	  return withMailbox(
183	    cred,
184	    folder,
185	    async (client) => {
186	      const term = search?.trim();
187	      const query = term
188	        ? { or: [{ subject: term }, { from: term }, { to: term }, { body: term }] }
189	        : { all: true };
190	      const found = await client.search(query, { uid: true });
191	      const uids = (Array.isArray(found) ? found : []).slice().sort((a, b) => b - a); // newest first
192	
193	      const total = uids.length;
194	      const start = (pageNum - 1) * PAGE_SIZE;
195	      const pageUids = uids.slice(start, start + PAGE_SIZE);
196	      if (pageUids.length === 0) {
197	        return { messages: [], total, page: pageNum, pageSize: PAGE_SIZE };
198	      }
199	
200	      // 1) Cheap metadata pass for the page.
201	      const metaByUid = new Map<number, MessageSummary>();
202	      const previewPartByUid = new Map<number, string>();
203	      for await (const msg of client.fetch(
204	        pageUids,
205	        { uid: true, envelope: true, flags: true, internalDate: true, bodyStructure: true },
206	        { uid: true },
207	      )) {
208	        const flags = readFlags(msg.flags);
209	        const env = msg.envelope;
210	        metaByUid.set(msg.uid, {
211	          uid: msg.uid,
212	          folder,
213	          from: toMailAddress(env?.from?.[0]),
214	          to: toMailAddresses(env?.to),
215	          subject: env?.subject || "(no subject)",
216	          preview: "",
217	          date: isoDate(msg),
218	          seen: flags.seen,
219	          flagged: flags.flagged,
220	          answered: flags.answered,
221	          hasAttachments: structureHasAttachments(msg.bodyStructure),
222	        });
223	        previewPartByUid.set(msg.uid, findPreviewPart(msg.bodyStructure).part);
224	      }
225	
226	      // 2) Snippet pass (partial, PEEKed downloads — no flag changes).
227	      await Promise.all(
228	        pageUids.map(async (uid) => {
229	          const summary = metaByUid.get(uid);
230	          if (!summary) return;
231	          summary.preview = await fetchPreview(client, uid, previewPartByUid.get(uid) || "1");
232	        }),
233	      );
234	
235	      const messages = pageUids
236	        .map((uid) => metaByUid.get(uid))
237	        .filter((m): m is MessageSummary => Boolean(m));
238	      return { messages, total, page: pageNum, pageSize: PAGE_SIZE };
239	    },
240	    { readOnly: true },
241	  );
242	}
