306	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
307	
308	/** Parse a comma/semicolon-separated recipient string into validated addresses. */
309	function parseRecipients(input: string | undefined): { list: string[]; invalid: string[] } {
310	  const parts = (input || "")
311	    .split(/[,;]+/)
312	    .map((s) => s.trim())
313	    .filter(Boolean);
314	  const list: string[] = [];
315	  const invalid: string[] = [];
316	  for (const p of parts) {
317	    // Tolerate "Name <addr>" form by extracting the address.
318	    const m = p.match(/<([^>]+)>/);
319	    const addr = (m ? m[1] : p).trim();
320	    if (EMAIL_RE.test(addr)) list.push(addr);
321	    else invalid.push(p);
322	  }
323	  return { list, invalid };
324	}
