593	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
594	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
595	  const { user, cred } = await resolveMailbox(mailboxAddress);
596	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
597	
598	  await withImap(cred, async (client) => {
599	    // Determine the Trash folder path.
600	    let trashPath = "Trash";
601	    try {
602	      const list = await client.list();
603	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
604	      if (trash) trashPath = trash.path;
605	    } catch {
606	      /* fall back to "Trash" */
607	    }
608	
609	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
610	    const lock = await client.getMailboxLock(folder);
611	    try {
612	      if (inTrash) {
613	        await client.messageDelete(String(uid), { uid: true });
614	      } else {
615	        await client.messageMove(String(uid), trashPath, { uid: true });
616	      }
617	    } finally {
618	      lock.release();
619	    }
620	  });
621	}
