681	/**
682	 * Mark a message as NOT spam: MOVE it from Junk back to Inbox. The move trains
683	 * Rspamd as ham when the host's imap_sieve antispam hooks are enabled (Mailcow
684	 * default) — same caveat as `markSpam`.
685	 */
686	export async function markNotSpam(fromFolder: string, uid: number, mailboxAddress?: string): Promise<void> {
687	  const { user, cred } = await resolveMailbox(mailboxAddress);
688	  enforceRateLimit(`mail:spam:${user.id}`, { max: 120, windowMs: 60 * 1000 });
689	
690	  await withImap(cred, async (client) => {
691	    const inboxPath = await resolveFolderPath(client, "inbox", "INBOX");
692	    if (fromFolder === inboxPath) return; // already in the inbox
693	    const lock = await client.getMailboxLock(fromFolder);
694	    try {
695	      await client.messageMove(String(uid), inboxPath, { uid: true });
696	    } finally {
697	      lock.release();
698	    }
699	  });
700	}
