702	/**
703	 * Block a sender: add their address to the mailbox's managed blocked-senders
704	 * sieve filter so FUTURE mail from them is filed straight to Junk. Reuses the
705	 * existing Mailcow sieve helpers (mcAddFilter/mcEditFilter) and runs as a
706	 * `postfilter`, separate from the auto-reply/forwarding `prefilter`, so the two
707	 * never disable each other (see lib/mail/sieve.ts).
708	 *
709	 * Returns a friendly `{ ok, error }` — a Mailcow/IMAP hiccup never throws out to
710	 * the mailbox view.
711	 */
712	export async function blockSender(
713	  senderAddress: string,
714	  mailboxAddress?: string,
715	): Promise<{ ok: boolean; error?: string }> {
716	  let ctx: Awaited<ReturnType<typeof resolveMailbox>>;
717	  try {
718	    ctx = await resolveMailbox(mailboxAddress);
719	  } catch (e) {
720	    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 200) };
721	  }
722	  const { user, cred, address, subscription } = ctx;
723	
724	  const gate = checkRateLimit(`mail:block:${user.id}`, { max: 30, windowMs: 60 * 1000 });
725	  if (!gate.ok) return { ok: false, error: `Too many requests — please wait ${gate.retryAfterSec}s and try again.` };
726	
727	  const target = (senderAddress || "").trim().toLowerCase();
728	  if (!target) return { ok: false, error: "There's no sender address to block." };
729	  if (!EMAIL_RE.test(target) || target.length > 254) {
730	    return { ok: false, error: "That doesn't look like a valid email address." };
731	  }
732	  if (target === address.toLowerCase()) return { ok: false, error: "You can't block your own address." };
733	
734	  if (!mailcowConfigured()) return { ok: false, error: "The mail server isn't configured yet — blocking is unavailable." };
735	  if (subscription.status === "CANCELLED") return { ok: false, error: "This subscription is cancelled." };
736	
737	  try {
738	    // Resolve the mailbox's real Junk path so `fileinto` targets the folder that
739	    // actually exists (defaults to "Junk" on Mailcow/Dovecot).
740	    const junkPath = await withImap(cred, (client) => resolveFolderPath(client, "junk", "Junk"));
741	
742	    // Read the current managed block filter (if any) and extend its list.
743	    const existing = (await mcListFilters(address)).filter((f) => isNxeonBlockSieve(f.scriptDesc));
744	    const current = existing[0] ? parseBlockedSenders(existing[0].scriptData) : [];
745	    if (current.includes(target)) return { ok: true }; // already blocked — idempotent
746	    if (current.length >= MAX_BLOCKED_SENDERS) {
747	      return { ok: false, error: `You've reached the ${MAX_BLOCKED_SENDERS}-sender block limit.` };
748	    }
749	
750	    const script = buildBlockSenderSieve([...current, target], junkPath);
751	    const [keep, ...duplicates] = existing;
752	    // Clean up any duplicate managed filters left by an interrupted save.
753	    for (const f of duplicates) await mcDeleteFilter(f.id);
754	
755	    if (keep) {
756	      await mcEditFilter(keep.id, {
757	        scriptDesc: NXEON_BLOCK_DESC,
758	        scriptData: script,
759	        filterType: NXEON_BLOCK_TYPE,
760	        active: true,
761	      });
762	    } else {
763	      await mcAddFilter({
764	        address,
765	        scriptDesc: NXEON_BLOCK_DESC,
766	        scriptData: script,
767	        filterType: NXEON_BLOCK_TYPE,
768	        active: true,
769	      });
770	    }
771	  } catch (e) {
772	    return { ok: false, error: `Couldn't apply the block on the mail server: ${String((e as Error)?.message ?? e).replace(/\s+/g, " ").slice(0, 180)}` };
773	  }
774	
775	  await db.auditLog
776	    .create({ data: { userId: user.id, action: "mailbox.blockSender", detail: `${address} blocked ${target}` } })
777	    .catch(() => {});
778	
779	  return { ok: true };
780	}
