802	/**
803	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
804	 * quota and address uniqueness within the subscription, records the intended
805	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
806	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
807	 */
808	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
809	  const user = await requireUser();
810	
811	  const sub = await db.emailSubscription.findUnique({
812	    where: { id: subscriptionId },
813	    include: { emailPlan: true, mailboxes: true },
814	  });
815	  if (!sub) return { error: "Subscription not found." };
816	  if (sub.userId !== user.id) return { error: "Not your subscription." };
817	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
818	  // SECURITY (added 2026-07-25): defence in depth against the cross-tenant
819	  // takeover fixed in subscribeEmail(). Owning the subscription ROW is not proof
820	  // of owning the DOMAIN — and because Mailcow keys mailboxes by address, any
821	  // mailbox minted here acts on that domain's real mail. An external domain must
822	  // prove control via DNS before it can mint a single address, so even if a
823	  // duplicate subscription is ever created again this cannot be weaponised.
824	  if (sub.external && !sub.verified) {
825	    return {
826	      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
827	    };
828	  }
829	
830	  const local = String(localPart ?? "").trim().toLowerCase();
831	  if (!localPartRe.test(local) || local.length > 64) {
832	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
833	  }
834	
835	  const address = `${local}@${sub.domainName}`;
836	
837	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
838	    return {
839	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
840	    };
841	  }
842	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
843	    return { error: "That address already exists." };
844	  }
845	
846	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
847	  const quotaMB = sub.emailPlan.storageGB * 1024;
