1123	/**
1124	 * Store a customer's Cloudflare API token (encrypted) so we can create their
1125	 * mail DNS records for them. The token is verified against Cloudflare before it
1126	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
1127	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
1128	 */
1129	export async function saveCloudflareToken(token: string): Promise<Result> {
1130	  const user = await requireUser();
1131	
1132	  const t = String(token ?? "").trim();
1133	  if (!t) return { error: "Paste your Cloudflare API token." };
1134	  if (t.length < 20 || t.length > 200) {
1135	    return { error: "That doesn't look like a Cloudflare API token." };
1136	  }
1137	
1138	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
1139	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
1140	
1141	  let valid = false;
1142	  try {
1143	    valid = await cfVerifyToken(t);
1144	  } catch (e) {
1145	    console.warn("[cloudflare] token verify failed:", e);
1146	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
1147	  }
1148	  if (!valid) {
1149	    return {
1150	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
1151	    };
1152	  }
1153	
1154	  await db.user.update({
1155	    where: { id: user.id },
1156	    data: { cloudflareTokenEnc: encryptSecret(t) },
1157	  });
1158	  await db.auditLog.create({
1159	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
1160	  });
1161	  revalidatePath("/dashboard/email");
