1165	/**
1166	 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
1167	 * customer's Cloudflare zone, using their stored token. Ownership-checked and
1168	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
1169	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
1170	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
1171	 * gracefully with clear messages for invalid token / zone-not-found.
1172	 */
1173	export async function autoCreateEmailDns(
1174	  subscriptionId: string,
1175	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
1176	  const user = await requireUser();
1177	
1178	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
1179	  if (!sub) return { error: "Subscription not found." };
1180	  if (sub.userId !== user.id) return { error: "Not your subscription." };
1181	  if (!sub.external) {
1182	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
1183	  }
1184	
1185	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
1186	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
1187	
1188	  // Works for both connection shapes: OAuth credentials (refreshed here when
1189	  // stale) and a legacy pasted API token. Never handles the plaintext itself.
1190	  const resolved = await resolveCloudflareToken(user);
1191	  const token = resolved.token;
1192	  if (!token) return { error: resolved.error ?? "Connect Cloudflare first." };
1193	
1194	  // Same record set the customer would otherwise publish by hand.
1195	  const dns = await getEmailDnsRecords(subscriptionId);
1196	  if (dns.error) return { error: dns.error };
1197	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
1198	  if (records.length === 0) {
1199	    return { error: "No DNS records to create yet — try again in a moment." };
1200	  }
1201	
1202	  // SANDBOX: never contact Cloudflare — report what we would have published so
1203	  // staging can walk the whole "connect → records added" flow.
1204	  if (SANDBOX) {
1205	    return {
1206	      ok: true,
1207	      created: records.map((r) => `${r.label} (${r.type}, created)`),
1208	    };
1209	  }
1210	
1211	  let zoneId: string | null;
1212	  try {
1213	    zoneId = await cfFindZoneId(token, sub.domainName);
1214	  } catch (e) {
1215	    if (e instanceof CloudflareError) {
1216	      return { error: `Cloudflare error: ${e.message}` };
1217	    }
1218	    throw e;
1219	  }
1220	  if (!zoneId) {
1221	    return {
1222	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
1223	    };
1224	  }
1225	
1226	  let created: string[];
1227	  try {
1228	    const results = await cfUpsertRecords(
1229	      token,
1230	      zoneId,
1231	      records.map((r) => ({
1232	        type: r.type,
1233	        name: r.host,
1234	        content: r.value,
1235	        priority: r.priority,
1236	      })),
1237	    );
1238	    created = results.map((res) => {
1239	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
1240	      return `${label} (${res.type}, ${res.action})`;
1241	    });
1242	  } catch (e) {
1243	    if (e instanceof CloudflareError) {
1244	      return {
1245	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
1246	      };
1247	    }
1248	    throw e;
1249	  }
1250	
1251	  await db.auditLog.create({
1252	    data: {
1253	      userId: user.id,
1254	      action: "cloudflare.autodns",
1255	      detail: `${sub.domainName} — ${created.length} record(s)`,
1256	    },
1257	  });
1258	  revalidatePath("/dashboard/email");
1259	  return { ok: true, created };
1260	}
